from pathlib import Path
import csv,json,gzip,shutil,numpy as np,html,hashlib
from PIL import Image
R=Path('outputs/deep-water-long-analysis');P=R/'gallery';P.mkdir(exist_ok=True);(P/'figures').mkdir(exist_ok=True);a=np.load(R/'stage-spectra.npz');stages=[100,300,600,900];rows=list(csv.DictReader((R/'directional-budgets.csv').open()))
def get(c,t,tag,lo,hi,sec):return next(x for x in rows if x['case']==c and int(x['stage_Te'])==t and x['window']==tag and int(x['band_lo'])==lo and int(x['band_hi'])==hi and x['sector']==sec)
def ratio(t,tag,lo,hi):
 x,y=[get(c,t,tag,lo,hi,'horizontal') for c in ['deep','control']];return float(x['energy'])/float(x['annulus_eddy_energy'])/(float(y['energy'])/float(y['annulus_eddy_energy']))
rat=[]
for t in stages:
 for d in [.5,.25,.125]:
  for method in ['hann','reflect']:
   for lo,hi in [(1,4),(4,8),(8,16),(16,24)]:
    x=get('deep',t,f'top{d}_{method}',lo,hi,'horizontal');valid=x['angular_comparison_valid']=='True';rat.append(dict(stage_Te=t,depth=d,method=method,band_lo=lo,band_hi=hi,resolvable=valid,horizontal_fraction_ratio=ratio(t,f'top{d}_{method}',lo,hi) if valid else None))
with (R/'angular-ratios.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(rat[0]));w.writeheader();w.writerows(rat)
for path in (R/'figures').glob('*.webp'):shutil.copy2(path,P/'figures'/path.name)
for path in (R/'figures').glob('*.pdf'):shutil.copy2(path,P/'figures'/path.name)
for name in ['directional-budgets.csv','evolution.csv','angular-ratios.csv','mean-gradient-sensitivity.csv']:
 with gzip.open(P/(name+'.gz'),'wb') as f:f.write((R/name).read_bytes())
for name in ['reduction-summary.json','independent-validation.json']:
 if (R/name).exists():shutil.copy2(R/name,P/name)
# Exact positive-K half-plane energy used for the main figure and its reflected comparison.
with gzip.open(P/'upper-quarter-spectra.csv.gz','wt',newline='') as f:
 w=csv.writer(f);w.writerow(['stage_Te','method','K_cycles','ell_cycles','deep_E','control_E'])
 for t in stages:
  for method in ['hann','reflect']:
   tag='top0.25_'+method;ell=a[tag+'_ell'];A=a[f'deep_{t}_{tag}_E'];B=a[f'control_{t}_{tag}_E']
   for i,l in enumerate(ell):
    for j,k in enumerate(a['k']):w.writerow([t,method,k,l,f'{A[i,j]:.12g}',f'{B[i,j]:.12g}'])
evo=np.genfromtxt(R/'evolution.csv',names=True,delimiter=',',dtype=None,encoding=None)
summary={'physical_target':'Deep-water waves with Stokes shear 0.25 exp(8z), us=0.03125 exp(8z), wave k=4, depth=2; kH=8','grid':[4096,2048],'Lx':4,'H':2,'seed_pairs':1,'seed':1,'duration_Te':1000,'initial_ring_cycles':27,'u0':float(a['u0']),'Te':float(a['Te']),'jobs':{'deep':'66766564_0','control':'66766564_1'},'stage_windows_Te':[[t-20,t+20] for t in stages],'final':{},'angular_ratios':rat,'interpretation':'Strong local anisotropy and mean-current growth. The full-depth conservative directional input is not uniformly suppressed across stages and bands; a resolved curved spectral bottleneck is not established by this one pair.'}
for c in ['deep','control']:
 q=evo[evo['case']==c];summary['final'][c]={'native_energy_ratio':float(q['native_energy'][-1]/q['native_energy'][0]),'horizontal_mean_energy_fraction_full_native':float(q['jet_fraction_full'][-1]),'horizontal_mean_energy_fraction_upper025_native':float(q['jet_fraction_top025'][-1])}
closure={}
for tag in ['full_native','top0.25_hann','top0.25_reflect']:
 q=[x for x in rows if x['window']==tag and x['band_lo']=='1' and x['band_hi']=='24'];rr=[abs(float(x['budget_residual']))/max(sum(abs(float(x['T_'+term])) for term in ['centered','wave','pressure','numerical','numerical_pressure']),1e-30) for x in q];closure[tag]={'median_relative_residual':float(np.median(rr)),'max_relative_residual':float(max(rr))}
summary['finite_time_budget_closure']=closure;(P/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(R/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
def fig(name,caption,alt=None):
 path=P/'figures'/(name+'.webp');im=Image.open(path);w,h=im.size
 return f'<figure><a href="figures/{name}.webp"><img src="figures/{name}.webp" width="{w}" height="{h}" loading="lazy" alt="{html.escape(alt or name)}"></a><figcaption>{caption}</figcaption></figure>'
style='''body{font:17px/1.65 system-ui,sans-serif;color:#18334a;background:#f6f8fa;max-width:1120px;margin:28px auto;padding:0 20px 60px}h1{font-size:2.1rem;line-height:1.2}h2{margin-top:2.2em}h3{margin-top:1.6em}a{color:#175a98}nav{display:flex;gap:16px;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid #cbd5de}img{display:block;width:100%;height:auto;background:white}figure{margin:25px 0}figcaption,.note{font-size:15px;color:#41576a}figcaption{padding:12px 4px}table{width:100%;border-collapse:collapse;background:#fff;font-size:15px}td,th{text-align:right;padding:9px;border-bottom:1px solid #d8e0e5}td:first-child,th:first-child{text-align:left}.scroll{overflow:auto}.finding{background:#fff;border-left:4px solid #3979a9;padding:12px 22px;margin:25px 0}details{border:1px solid #cad6df;border-radius:5px;margin:20px 0;padding:12px 18px;background:#fff}summary{font-weight:600;cursor:pointer}code{font-size:.88em}section{scroll-margin-top:18px}@media(max-width:600px){body{padding:0 12px;font-size:16px}h1{font-size:1.7rem}td,th{padding:6px}}'''
h=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Deep-water current spectra to 1000 eddy times</title><style>{style}</style></head><body>'
h+='''<a href="../">← Spectral-exclusion gallery</a><h1>Deep-water current spectra to 1000 eddy times</h1><p>Exponential Stokes profile · 4096 × 2048 · one matched seed pair · 5 November 2026</p><nav><a href="#stage-100">100 T<sub>e</sub></a><a href="#stage-300">300 T<sub>e</sub></a><a href="#stage-600">600 T<sub>e</sub></a><a href="#stage-900">900 T<sub>e</sub></a><a href="#transfer">Directional transfer</a><a href="#methods">Methods &amp; data</a></nav>
<div class="finding"><p><strong>The upper-layer spectra become strongly anisotropic as the jets develop.</strong> At 900 T<sub>e</sub>, the off-axis energy fraction in the 16–24-cycle band is about 90–91% below the matched no-wave control in the upper 0.25 depth, with both estimators agreeing. The 8–16-cycle band is about 78% lower.</p><p><strong>A curved cascade bottleneck is not yet established.</strong> The spectra show concentration near the jet axis, but the full-depth conservative nonlinear input is not consistently suppressed across bands and stages. Local-window budgets also contain substantial pressure and vertical-transport contributions. These are results from one seed pair, not an ensemble.</p></div>
<h2>The experiment</h2><p>The prescribed deep-water Stokes shear is ∂<sub>z</sub>u<sup>s</sup> = 0.25e<sup>8z</sup>, with u<sup>s</sup> = 0.03125e<sup>8z</sup> and surface-wave wavenumber k = 4. The domain is 0 ≤ x &lt; 4, −2 ≤ z ≤ 0, so kH = 8. Both exactly two-dimensional runs use the same seed-1 initial ring at 27 cycles per original unit length, u<sub>0</sub> = 1.563598513 × 10<sup>−4</sup>, and T<sub>e</sub> = 37.69911184. Evolution uses WENO9/RK3. One run has waves; its control has none. No constant-gradient run is used for this result.</p>
<h2>Velocity above spatial spectra</h2><p>Each velocity panel is a single snapshot at the stated time. Each spectrum is a trapezoidal time average over the surrounding 40 T<sub>e</sub>, using 41 outputs from that same seed. The dashed line marks the main spectral window, −0.25 &lt; z &lt; 0. Both cases share the velocity scale and, within each spectral row, the same energy normalization.</p>'''
for t in stages:
 h+=f'<section id="stage-{t}"><h3>{t} T<sub>e</sub></h3>'
 h+=fig(f'velocity-spectra-{t}',f'Velocity at {t} T<sub>e</sub>; spectra averaged over {t-20}–{t+20} T<sub>e</sub>. Middle: total energy. Bottom: the exact K = 0 mode removed before display binning; the central display bin still contains nearby nonzero K modes. Direct Hann window, D = 0.25. The grey contours use horizontal bins of width 4 cycles, matching the vertical spacing. Contours interpolate between these bins; they do not add independent spectral information. Each row uses its own wave/control common maximum. <a href="figures/velocity-spectra-{t}.pdf">PDF</a>.',f'Horizontal currents above total and nonzero-K spatial spectra at {t} eddy times, deep-water and no-wave pair')
 h+=f'<details><summary>Native Fourier samples and window sensitivity at {t} T<sub>e</sub></summary>'
 h+=fig(f'velocity-spectra-{t}-native','Same fields and averages, with the original horizontal/vertical Fourier samples shown directly on a logarithmic grey scale. No horizontal display aggregation, zero padding or spectral smoothing. The colour normalization differs from the binned contour view because the displayed energy bins differ.')
 h+=fig(f'window-sensitivity-{t}','Nonzero-K spectra for D = 0.5, 0.25 and 0.125, with direct Hann and reflected estimators. Each adjacent wave/control pair shares a scale. These are actual Fourier samples, not padded grids. The reflected estimator retains the surface while tapering the bottom quarter; Hann downweights both endpoints. Differences combine depth weighting and spectral resolution. The reflected ℓ = 0 stripe is boundary/parity dependent and is not evidence for exclusion.')
 h+='</details></section>'
h+='<h2>How much directional depletion?</h2>'
h+=fig('angular-depletion','Wave/control ratio of the off-axis fraction of nonzero-K energy within each annulus. Off axis means |K|/κ ≥ √3/2; the comparison vertical sector has |K|/κ ≤ 1/2. Solid: Hann; dashed: reflection. Reflected ℓ = 0 modes are omitted from this angular comparison. Missing points lack samples in one comparison sector and are unresolvable, not zero depletion. Lines connect the four prescribed stage averages; they are not confidence intervals.')
h+='<div class="scroll"><table><tr><th>Stage</th><th>8–16, Hann</th><th>8–16, reflected</th><th>16–24, Hann</th><th>16–24, reflected</th></tr>'
for t in stages:h+='<tr><td>'+str(t)+' T<sub>e</sub></td>'+''.join(f'<td>{ratio(t,"top0.25_"+m,lo,hi):.3f}</td>' for lo,hi,m in [(8,16,'hann'),(8,16,'reflect'),(16,24,'hann'),(16,24,'reflect')])+'</tr>'
h+='</table></div><p class="note">Ratios for D = 0.25. Values below 1 indicate a smaller off-axis energy fraction with waves. This is an angular fraction, not an absolute-energy ratio or a measurement of nonlinear flux.</p>'
h+='<section id="transfer"><h2>Does nonlinear transfer establish a bottleneck?</h2><p>The preselected test compares net conservative nonlinear input into fixed off-axis regions and a near-jet cone, |K|/κ ≤ 0.1. Positive input supplies energy; negative input removes it. The full-depth native calculation provides a conservative advection diagnostic without an artificial depth-window boundary. It includes the dynamically different lower layer, so it cannot by itself isolate an upper-layer barrier.</p>'
h+=fig('directional-transfer','Full-depth native conservative nonlinear input, normalized by E₀/Tₑ, in four disjoint radial bands. Off-axis and near-axis regions are fixed in advance. Positive values are net input to the selected region, not a separately measured angular-boundary flux. The near-axis cone includes K = 0. No uniform suppression of off-axis input appears across the four stages.')
h+=fig('directional-budget','Full-depth budgets over 1 ≤ κ/(2π) &lt; 24. Conservative nonlinear input, wave contribution, numerical advection correction and the measured finite-time energy change are shown separately. Pressure makes no appreciable full-depth modal contribution for the divergence-free native fields. Near-axis and K = 0 panels overlap; they must not be added as disjoint regions. All four deep-water stage averages have positive nonlinear input to the K = 0 region shown here.')
h+='<details><summary>Local pressure/transport, interaction split and radial flux</summary>'
h+=fig('local-window-budget','Upper-quarter Hann-window budget over 1 ≤ κ/(2π) &lt; 24. Local nonlinear work includes transport through the window; pressure work is also substantial. Consequently, local nonlinear work alone is not a conservative cascade flux. Numerical advection and its pressure correction are included in the downloadable closure data, but omitted from this plot for readability. The pressure operator is evaluated from the instantaneous tendencies, separately from the last RK-stage pressure.')
h+=fig('interaction-split','Deep-water full-depth nonlinear input split into eddy–eddy and mean–eddy advection, over the same 1–24-cycle regions. This splits the advecting interactions; it does not remove mean receiving modes. The total is their sum. The K = 0 input is predominantly the eddy–eddy contribution.')
h+=fig('radial-transfer','Full-depth conservative diagnostic flux Π(κc) = −Σκ&lt;κc T<sub>centered</sub>. Negative means net transfer into lower wavenumbers. Upscale transfer persists at several cutoffs; a negative radial flux is compatible with a directional barrier and is not a rejection criterion by itself.')
h+='</details></section>'
h+=fig('energy-and-jets','Evolution of native-grid kinetic energy and the horizontal-mean current energy fraction. The latter is ½⟨Uᴸ²⟩ divided by kinetic energy over the same depth interval. It excludes slowly varying nonzero-K bands. Final full-depth fractions are about 21.2% with deep-water waves and 5.9% in the control. This demonstrates stronger mean currents, not by itself a bottleneck.')
h+='<details><summary>The evolving mean current changes the effective gradient</summary>'
h+=fig('mean-current-gradient','Horizontal-mean velocity and effective gradient at the four snapshot times. For waves, Qz = −2e<sup>8z</sup> + Uᴸ<sub>zz</sub>; for the control, Qz = Uᴸ<sub>zz</sub>. Curvature is computed with the free-slip cosine basis and Gaussian diagnostic smoothing σ = 0.01; the evolving fields are not altered. At 900 Tₑ, the RMS mean-current curvature is 37% of the prescribed Stokes-gradient RMS over −0.25 &lt; z &lt; −0.03. Varying σ from 0.005 to 0.02 gives 44% to 19%, so the precise derivative estimate is filter dependent. A fixed prescribed-gradient curve is therefore not the full late-time effective background.')
h+='</details><section id="methods"><h2>Resolution and interpretation</h2><p>At D = 0.25 the direct vertical bin spacing is 1/D = 4 cycles; reflection gives a 2-cycle spacing by extending the data, not by adding independent observations. At D = 0.125 those spacings become 8 and 4. The Stokes gradient changes by e² ≈ 7.4 across the full D = 0.25 support, and by e ≈ 2.7 across D = 0.125. Thinner windows make the background more local while reducing vertical spectral resolution. The 1–4-cycle angular comparison is unresolvable in the upper-quarter window. The 4–8-cycle result is estimator sensitive. These limitations prevent a reliable fitted curved exclusion boundary here.</p><p>All spectra use the native-resolution fields. Velocity images alone are averaged over 4 × 4 cells for display; their vertical scale is expanded for readability, and colours clip outside ±4u₀. Local spectra collocate staggered velocities, apply the stated taper and divide by its mean square. Signed-K displays reconstruct conjugate partners from the stored positive-K half-plane; K &gt; 0 multiplicity is undone before mirroring. The retained range is |K|/(2π), |ℓ|/(2π) ≤ 40. No fitted Rhines curve, zero padding or spectral smoothing is applied.</p>'
h+='<h3>Validation and limits</h3><p>All 2,002 online diagnostic files passed the stored conservation, pressure-projection and Parseval checks; the largest retained-horizontal Parseval discrepancy is 6.8 × 10<sup>−16</sup>. Independent SciPy transforms of the archived velocity fields check all three local depths, both estimators and all four stages. The two runs have identical initial velocity files. Finite-time budget checks use the 40-Tₑ energy change and the sampled instantaneous tendencies; they are not exact RK-step closure. Across the listed 1–24-cycle regions, the median relative residual is 0.18% for the full-depth budget and 0.13% for the upper-quarter Hann budget; maxima are 14.5% and 5.2%, respectively, including small-net-input regions. No grid-convergence or across-seed reproducibility claim follows from this one pair.</p>'
h+='<h3>Downloads and source</h3><ul><li><a href="directional-budgets.csv.gz">All directional energies, transfer components and finite-time closure residuals (CSV.gz)</a></li><li><a href="angular-ratios.csv.gz">Window/estimator angular ratios and resolvability flags (CSV.gz)</a></li><li><a href="mean-gradient-sensitivity.csv.gz">Mean-gradient smoothing sensitivity (CSV.gz)</a></li><li><a href="summary.json">Summary and configuration</a> · <a href="reduction-summary.json">Reduction checks</a> · <a href="independent-validation.json">Independent transform validation</a></li><li><a href="https://github.com/npizzo/wave-current-gallery/tree/main/scripts/deep-water-long">Reduction and plotting source</a></li></ul><p class="note">Full wavenumber-resolved arrays, evolution records, native fields, raw tendency windows and restart checkpoints remain archived on Unity. The public downloads here contain sector-budget aggregates, angular ratios and numerical checks. This publication analyzes the two completed runs; it launches no new simulations.</p></section></body></html>'
(P/'index.html').write_text(h)
